"▲ TAP = HOP · HOLD = FLY":"▲ 點擊 = 跳躍 · 長按 = 飛行",
"LAZY JO · LEVEL #":"LAZY JO · 第#關",
"The beach from the cover, at sunset. Hop the saucer across the sea to the stone arch before the sun goes down.":"日落時分封面上的海灘。在太陽下山前，駕駛飛碟跳躍渡海，抵達石拱門。",
"THE SEA GOT YOU":"掉進海裡了",
"BEAM":"光束",
"THE ARCH FELL":"拱門倒塌了",
"The saucer skims the sea toward the sun. Jump the big waves, keep off the rocks, grab the lights.":"飛碟掠過海面飛向太陽。跳過大浪，避開岩石，抓住光點。",
"WIPEOUT":"撞毀了",
"THE SONG":"歌曲",
"THE JOURNEY":"旅程",
"From the Earth in your hands to Planet Javeda, in the little orange ship. Every planet on the way is under a meteor shower.":"乘著橘色小飛船，從你手中的地球飛往Javeda星球。沿途的每顆星球都籠罩在流星雨之下。",
"The long way home: the meteors hunt you in flight too, and you start with # hearts.":"漫長的回家路：飛行中流星也會追擊你，開局只有#顆愛心。",
"PETAL RAIN":"花瓣雨",
"The rose in the canyon is losing its petals. Catch them in the saucer's green beam before they hit the cracked ground.":"峽谷裡的玫瑰正在凋落。在花瓣落到龜裂的地面之前，用飛碟的綠色光束接住它們。",
"ROSE # / #":"玫瑰 # / #",
"THE ROSE LOST ALL ITS PETALS":"玫瑰的花瓣掉光了",
"Climb the giant stem all the way to the bloom - round the thorns, through the dew.":"沿著巨大的花莖一路爬到花朵 - 繞過尖刺，穿過露珠。",
"THROUGH THE GAP":"穿過縫隙",
"# M · # IN A ROW":"#公尺 · #連擊",
"SHADOW # S BEHIND":"影子落後#秒",
"YOUR SHADOW GOT YOU":"你被影子抓到了",
"THE KING OF FORGETTING":"遺忘之王",
"LAZY JO × ZIRKA · LEVEL #":"LAZY JO × ZIRKA · 關卡#",
"NIGHT FLIGHT":"夜間飛行",
"District #, the night the monsters of forgetting came. Fly Jo's saucer between the neon towers and light them up.":"第#區，遺忘怪獸來襲的那一夜。駕駛Jo的飛碟穿梭在霓虹大樓之間，把它們點亮。",
"# DOWN":"擊落#",
"STORM #s":"風暴 #秒",
"THE SWARM!":"怪群來了！",
"LAZY JO × ZIRKA · LEVEL # PART #":"LAZY JO × ZIRKA · 關卡# 第#部分",
"Zirka's bike over the rooftops of District # - jump the gaps on the beat, and Zirka's gun takes care of what dives in.":"Zirka騎著機車飛越第#區的屋頂 - 踩準節拍跳過缺口，俯衝過來的敵人交給Zirka的槍。",
"# BOLTS · # DOWN":"閃電# · 擊落#",
"x# · # BOLTS · # DOWN":"x# · 閃電# · 擊落#",
"The King of Forgetting hangs over the city. Bring him down before the song ends. Gadgets float up for Jo - and the wolf token hands the fight to Zirka on the roof below.":"遺忘之王懸在城市上空。在歌曲結束前把他打下來。道具會為Jo飄上來 - 狼徽章會把戰鬥交給下方屋頂上的Zirka。",
"x# · # CORE HITS":"x# · 核心命中#",
"# CORE HITS":"核心命中#",
"Jo's orange saucer drops into the city from the sky. Freefall down between the towers - through the skybridges, past the cranes and the helicopters - all the way to the streets.":"Jo的橘色飛碟從天而降，衝進城市。在大樓之間自由落體 - 穿過空橋，避開吊車和直升機，一路落到街道上。",
"# M DOWN":"下降#公尺",
"A CRANE!":"吊車！",
"A night race through the city, towards the moon, in Jo's silver car - its tail lights drawing a trail of light behind it. Seven cars start ahead of you: drift round the corners, hit the nitro on the beat and be first to the river.":"開著Jo的銀色跑車，在夜色中穿城飛馳，奔向月亮 - 尾燈在身後拖出一道光軌。七輛車在你前面出發：彎道甩尾，踩準節拍開氮氣，第一個衝到河邊。",
"P# · # KM/H":"第#名 · #km/h",
"Across the hologram clockwork on the stage. Jo's saucer hooks its beam onto the pendulums - swing, let go, fly, hook the next one. Make it all the way before the song runs out.":"穿越舞台上的全像鐘錶機關。Jo的飛碟用光束勾住鐘擺 - 擺盪、放開、飛出、勾住下一個。在歌曲結束前抵達終點。",
"# M · # ON THE BEAT":"#公尺 · 踩準節拍#次",
"YOU FELL":"你掉下去了",
"The room from the cover, from above. Jo's saucer never stops - it draws a trail of light on the rug wherever it goes. Make it the longest light in the room.":"從上方俯瞰封面裡的房間。Jo的飛碟永不停下 - 它走到哪裡，就在地毯上畫出一道光軌。讓它成為房間裡最長的光。",
"TRAIL # M":"光軌 #公尺",
"CROSSED!":"撞線了！",
"Inside the neon cup from the cover. The saucer is the paddle, a purple drop is the ball - smash the ice cubes and the pink splash before the ice comes down to you.":"在封面裡的霓虹杯子中。飛碟是球拍，紫色水滴是球 - 在冰塊壓下來之前，砸碎冰塊和粉紅水花。",
"# BROKEN · # LEFT":"已擊碎# · 剩餘#",
"# BROKEN · # LEFT · # IN A ROW":"已擊碎# · 剩餘# · #連擊",
"THE ICE COMES DOWN":"冰塊壓下來了",
"MISSED IT":"沒接住",
"The old houses on the street from the cover, at dusk, in the fog. Ghosts come up in the windows on the beat - catch them with the saucer's beam before they duck away.":"封面裡那條街上的老房子，黃昏，霧中。幽靈會隨著節拍出現在窗口 - 在它們躲起來之前用飛碟的光束抓住。",
"# CAUGHT · HAUNTED #/#":"抓到# · 鬧鬼 #/#",
"HAUNTED":"鬧鬼了",
"LAZY JO FEAT. ZIRKA · LEVEL #":"LAZY JO FEAT. ZIRKA · 關卡#",
"A purple and gold court floating in the white sky from the cover, Zirka's saucer up by the hoop. Hold to wind up, let go in the green - on the beat it's a swish.":"封面中漂浮在白色天空裡的紫金球場，Zirka的飛碟停在籃框旁。長按蓄力，在綠色區域放開 - 踩準節拍就是空心進球。",
"Warm up on your own":"自己熱身",
"#/# IN · # SWISH":"#/# 命中 · 空心#",
"The blue sky and the islands from the cover. A gold frame stands in the sea; Jo's saucer carries the pieces down in its beam - island chunks, gold, sky, cloud. Fill a row and it bursts gold.":"封面裡的藍天和島嶼。海中立著一個金色框架，Jo的飛碟用光束把方塊運下來 - 島嶼碎塊、黃金、天空、雲朵。填滿一行，它就會金光四濺。",
"# ROWS":"#行",
