"A car park on the wet street from the cover, at night, in the rain. The blue car is boxed in - slide the others out of its way so it can drive out.":"封面裡濕漉漉街道上的停車場，雨夜。藍色的車被堵住了 - 把其他車滑開，讓它開出去。",
