"Jo's studio at night from the cover - the big speakers, the screen with the crowd, the skull on the desk. On the desk the drum machine: # pads lit from under, each its own note, and Jo's saucer hovering over them.":"封面裡夜晚的Jo的工作室 - 大喇叭、顯示觀眾的螢幕、桌上的骷髏頭。桌上是鼓機：#個從下方發光的打擊墊，每個都是一個音，Jo的飛碟懸在它們上方。",
