"A purple and gold court floating in the white sky from the cover, Zirka's saucer up by the hoop. Hold to wind up, let go in the green - on the beat it's a swish. <b>Endless:</b> the shots never stop - harder every # bars, a heart back every #.":"封面白色天空中漂浮著紫金色球場，Zirka的飛碟停在籃框旁。長按蓄力，在綠色區域放手 - 踩準節拍就是空心球。<b>無盡模式：</b>投籃永不停止 - 每#小節變難一次，每#小節回一顆愛心。",
