"Peace inside.<br>Level # cleared: <b>Hoops ∞</b> is open in the gold Endless list.":"Peace inside.<br>第#關已過關：金色無盡模式列表裡的<b>Hoops ∞</b>已解鎖。",
"Hold to wind up and let go while the marker is in the green - two bars on the clock. <b>Go again.</b>":"長按蓄力，標記在綠色區域時放手 - 限時兩小節。<b>再來一次。</b>",
"Inside the neon cup from the cover. The saucer is the paddle, a purple drop is the ball - smash the ice cubes and the pink splash before the ice comes down to you. <b>Endless:</b> the ice never stops pouring in - faster every # bars, a heart back every #.":"封面上那只霓虹杯子裡。飛碟是擋板，紫色水滴是球 - 在冰塊壓下來之前，打碎冰塊和粉紅色水花。<b>無盡模式：</b>冰塊倒個不停 - 每#小節變快，每#小節回一顆愛心。",
