"The city at sunset from the cover, high over the towers - the sky going from purple to fire, the towers lit. <b>Part # · Rooftop Golf:</b> nine holes on the roofs, every one with something new. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上日落時分的城市，高懸在大樓之上 - 天空從紫色燒成火紅，大樓燈火通明。<b>第#部分 · Rooftop Golf：</b>屋頂上的九個洞，每一洞都有新花樣。<b>無盡模式：</b>永不停止 - 每#小節變難，每#小節回一顆愛心。",
"The city at sunset from the cover, high over the towers - the sky going from purple to fire, the towers lit. <b>Part # · Sky Hockey:</b> air hockey on a roof against the shadow, round after round. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上日落時分的城市，高懸在大樓之上 - 天空從紫色燒成火紅，大樓燈火通明。<b>第#部分 · Sky Hockey：</b>在屋頂上和影子打空氣曲棍球，一回合接一回合。<b>無盡模式：</b>永不停止 - 每#小節變難，每#小節回一顆愛心。",
"The night from the cover - the stars, the lasers crossing over the black car with the glowing pink hood and the rider on its roof - and Jo's saucer. <b>Part # · Neon Pinball:</b> a real pinball table on the floor in front of the car. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的夜晚 - 星星，雷射交錯掠過那輛粉紅色發光引擎蓋的黑色汽車和車頂上的騎士 - 還有Jo的飛碟。<b>第#部分 · Neon Pinball：</b>車前地面上一台真正的彈珠台。<b>無盡模式：</b>永不停止 - 每#小節變難，每#小節回一顆愛心。",
"The night from the cover - the stars, the lasers crossing over the black car with the glowing pink hood and the rider on its roof - and Jo's saucer. <b>Part # · Speaker Push:</b> the dance floor, the speakers off, the pads where they belong. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的夜晚 - 星星，雷射交錯掠過那輛粉紅色發光引擎蓋的黑色汽車和車頂上的騎士 - 還有Jo的飛碟。<b>第#部分 · Speaker Push：</b>舞池裡，喇叭沒開，發光墊標出它們該去的位置。<b>無盡模式：</b>永不停止 - 每#小節變難，每#小節回一顆愛心。",
"The wet street from the cover at night, in the rain. The saucer's beam goes flat across it - bend it with the mirrors so it reaches the car's headlights. <b>Endless:</b> it never stops - the clock gets shorter every # bars, a heart back every #.":"封面上雨夜裡濕漉漉的街道。飛碟的光束平平地橫穿過去 - 用鏡子把它折過去，照到汽車的車頭燈。<b>無盡模式：</b>永不停止 - 每#小節時間變短，每#小節回一顆愛心。",
"A car park on the wet street from the cover, at night, in the rain. The blue car is boxed in - slide the others out of its way so it can drive out. <b>Endless:</b> it never stops - the clock gets shorter every # bars, a heart back every #.":"封面上濕漉漉街道旁的停車場，雨夜。藍色的車被堵住了 - 把其他車滑開，讓它開出去。<b>無盡模式：</b>永不停止 - 每#小節時間變短，每#小節回一顆愛心。",
"The crowd from the cover under the blue light, every hand up, the big white light behind - and nine lights over them, each its own note. Jo's saucer hovers by the one you play. <b>Endless:</b> the pattern never stops - less time every # bars, a heart back every #.":"封面上藍光下的人群，人人舉起雙手，身後是巨大的白光 - 頭頂有九盞燈，每盞都有自己的音。Jo的飛碟會停在你按的那盞旁邊。<b>無盡模式：</b>序列永不停止 - 每#小節時間變少，每#小節回一顆愛心。",
"Across the hologram clockwork on the stage. Jo's saucer hooks its beam onto the pendulums - swing, let go, fly, hook the next one. Make it all the way before the song runs out. <b>Endless:</b> the clockwork never ends - wider every # bars, a heart back every #.":"穿越舞台上的全像發條機關。Jo的飛碟用光束勾住鐘擺 - 擺盪、放開、飛出、勾住下一個。在歌曲結束前一路通過。<b>無盡模式：</b>發條機關沒有盡頭 - 每#小節間距變寬，每#小節回一顆愛心。",
"The room from the cover, from above. Jo's saucer never stops - it draws a trail of light on the rug wherever it goes. Make it the longest light in the room. <b>Endless:</b> it never ends - faster every # bars, a heart back every #.":"俯瞰封面上的房間。Jo的飛碟停不下來 - 它走到哪裡，就在地毯上畫出一道光跡。讓它成為房間裡最長的光。<b>無盡模式：</b>永無止境 - 每#小節變快，每#小節回一顆愛心。",
