"<b>#</b> up all night · # passed on":"通宵 <b>#</b> · 傳遞#次",
"Score <b>#</b> · # m · # pendulums · # sparks · # on the beat":"分數 <b>#</b> · #公尺 · #個鐘擺 · #個火花 · 踩準節拍#次",
"<b>#</b> of swinging · # m · # pendulums · # sparks · # on the beat":"擺盪 <b>#</b> · #公尺 · #個鐘擺 · #個火花 · 踩準節拍#次",
