"The heart keeps breaking. Mend it, and its pieces scatter again. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"心一次又一次地碎裂。修好它，碎片又會再次散落。每塊碎片都有<b>倒數計時</b>，每一輪幽靈都會更快、更多。<b>#顆愛心</b>：碰到幽靈或碎片超時會扣一顆，每#小節回復一顆。",
"The heart keeps breaking. Mend it, and its pieces scatter again in the thick fog. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"心一次又一次地碎裂。修好它，碎片又會在濃霧中再次散落。每塊碎片都有<b>倒數計時</b>，每一輪幽靈都會更快、更多。<b>#顆愛心</b>：碰到幽靈或碎片超時會扣一顆，每#小節回復一顆。",
"The heart keeps breaking. Mend it, and its pieces scatter again, glowing only on the heartbeat. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"心一次又一次地碎裂。修好它，碎片又會再次散落，只在心跳時發光。每塊碎片都有<b>倒數計時</b>，每一輪幽靈都會更快、更多。<b>#顆愛心</b>：碰到幽靈或碎片超時會扣一顆，每#小節回復一顆。",
