"Survived <b>#</b> · <b>#</b> pieces · <b>#</b> hearts mended · lap <b>#</b>":"存活 <b>#</b> · <b>#</b>塊碎片 · 修好<b>#</b>顆心 · 第<b>#</b>圈",
