"All three parts in one night that never ends: every <b># bars</b> the forest turns into the next part, #, #, # and round again, harder each lap (<b>+#</b> and a heart back). <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"三個部分融進一個永無止境的夜晚：每<b>#小節</b>森林就會變成下一個部分，#、#、#，然後再循環，每圈都更難（<b>+#</b>並回復一顆愛心）。<b>#顆愛心</b>：碰到幽靈或碎片超時會扣一顆，每#小節回復一顆。",
