"Score <b>#</b> · # of # planets · # meteors bounced · # planets saved clean":"分數 <b>#</b> · 星球 #/# · 彈開#顆流星 · 零失誤守住#顆星球",
"Score <b>#</b> · # of # planets · # meteors bounced":"分數 <b>#</b> · 星球 #/# · 彈開#顆流星",
"Score <b>#</b> · # of # planets · # meteors bounced (# on the beat)":"分數 <b>#</b> · 星球 #/# · 彈開#顆流星（#顆踩準節拍）",
"From the Earth to Planet Javeda. <b>What a journey.</b><br>Part #: meteor showers and asteroids.":"從地球到Javeda星球。<b>好一段旅程。</b><br>第#部分：流星雨和小行星。",
