"<b>ENDLESS:</b> the song never ends and neither do the planets. Faster, busier, narrower - till the hearts run out. A heart back every # bars.":"<b>無盡模式：</b>歌曲永不結束，星球也沒有盡頭。更快、更忙、更窄 - 直到愛心用完。每#小節回復一顆愛心。",
"<b>#</b> survived · <b>#</b> planets reached · # meteors bounced (# on the beat)":"存活<b>#</b> · 抵達<b>#</b>顆星球 · 彈開#顆流星（#顆踩準節拍）",
"<b>#</b> survived · <b>#</b> planets reached · # meteors bounced":"存活<b>#</b> · 抵達<b>#</b>顆星球 · 彈開#顆流星",
"<b>#</b> survived · <b>#</b> planets reached · lap # · # meteors bounced (# on the beat)":"存活<b>#</b> · 抵達<b>#</b>顆星球 · 第#圈 · 彈開#顆流星（#顆踩準節拍）",
"<b>#</b> survived · <b>#</b> planets reached · lap # · # meteors bounced":"存活<b>#</b> · 抵達<b>#</b>顆星球 · 第#圈 · 彈開#顆流星",
"<b>REMIX:</b> all three parts in one endless trip. Each planet takes the next part's rules - Journey, Meteor Shower, The Long Way Home - and every lap is harder. +# and a heart back per lap.":"<b>混音模式：</b>三個部分串成一趟無盡旅程。每顆星球採用下一部分的規則 - Journey、Meteor Shower、The Long Way Home - 每一圈都更難。每圈+#並回復一顆愛心。",
