"He is on foot now, on a planet that isn't his. <b>That is the album.</b>":"現在他徒步走在一顆不屬於他的星球上。<b>這就是這張專輯。</b>",
"No finish line. The road goes on, faster and meaner, till the hearts run out. <b id=\"hn\"># hearts</b> · one back every # bars. Every metre is a point.":"沒有終點線。道路越來越快、越來越險，直到愛心用完。<b id=\"hn\">#顆愛心</b> · 每#小節回復一顆。每一公尺都是一積分。",
