"The blue sky and the islands from the cover. A gold frame stands in the sea; Jo's saucer carries the pieces down in its beam - island chunks, gold, sky, cloud. Fill a row and it bursts gold. <b>Endless:</b> the pieces never stop - quicker every # bars, a heart back every #.":"封面上的藍天和島嶼。海中立著一個金色框架；Jo的飛碟用光束把方塊運下來 - 島嶼碎塊、金塊、天空、雲朵。填滿一列，它就會迸發金光。<b>無盡模式：</b>方塊永不停止 - 每#小節變快一次，每#小節回復一顆愛心。",
