"RIDE TO THE SUN<small>◀ ▶ lanes · ▲ jump the waves</small>":"衝向太陽<small>◀ ▶ 換道 · ▲ 跳過海浪</small>",
"ROCK!<small># heart left</small>":"撞到石頭！<small>剩#顆愛心</small>",
