"Survived <b>#</b> · # lights · # waves jumped":"存活 <b>#</b> · 光點#個 · 跳過#道浪",
"Survived <b>#</b> · lap # · died in Island Hopper":"存活 <b>#</b> · 第#圈 · 倒在 Island Hopper",
"Survived <b>#</b> · lap # · died in Crab Night":"存活 <b>#</b> · 第#圈 · 倒在 Crab Night",
"Survived <b>#</b> · lap # · died in Surf the Sunset":"存活 <b>#</b> · 第#圈 · 倒在 Surf the Sunset",
"No rest, no work. <b>You made it.</b>":"不休息，不工作。<b>你做到了。</b>",
"No rest, no work. <b>You made it.</b><br>Part #: Crab Night - hold the arch.":"不休息，不工作。<b>你做到了。</b><br>第#部分：Crab Night - 守住石拱。",
"No rest, no work. <b>You made it.</b><br>Part #: surf the sunset.":"不休息，不工作。<b>你做到了。</b><br>第#部分：衝浪追夕陽。",
"Jump right at the edge, and hold to hover over the long gaps. <b>Go again.</b>":"在邊緣起跳，長按懸停越過長缺口。<b>再來一次。</b>",
"Keep moving - the arch is at the end of the beach. <b>Go again.</b>":"別停 - 石拱在海灘盡頭。<b>再來一次。</b>",
"Five crabs on the arch is too many. Shoot on the beat - it's free and it never overheats. <b>Go again.</b>":"石拱上有五隻螃蟹就完了。踩準節拍射擊 - 免費，而且永不過熱。<b>再來一次。</b>",
"Beam the nearest crab first, and shoot on the beat - it's free. <b>Go again.</b>":"先射最近的螃蟹，踩準節拍射擊 - 免費。<b>再來一次。</b>",
"Jump when the foam of the wave reaches you, and keep to the open lane. <b>Go again.</b>":"浪花碰到你時起跳，待在空著的賽道上。<b>再來一次。</b>",
"<b>Endless.</b> The beach never ends: rock to palm to rock, faster and wider the longer you last. The song loops - play till you're out.":"<b>無盡模式。</b>海灘沒有盡頭：從岩石到棕櫚再到岩石，撐越久越快、間距越寬。歌曲循環播放 - 玩到出局為止。",
"<b>Endless.</b> The sun never sets and the crabs never stop - bigger crowds, faster crabs. The song loops - play till you're out.":"<b>無盡模式。</b>太陽永不落下，螃蟹永不停歇 - 數量更多，速度更快。歌曲循環播放 - 玩到出局為止。",
"<b>Endless.</b> The sea never ends: faster, more rocks, and the waves keep coming. The song loops - play till you're out.":"<b>無盡模式。</b>大海沒有盡頭：更快，更多岩石，海浪接連不斷。歌曲循環播放 - 玩到出局為止。",
"<b>Tap</b> for a short hop, <b>hold</b> for a high jump and to hover with the beam (the HOVER bar refills when you land). Fall in the sea and it costs a heart - you have #, and green hearts float over some gaps. A heart back every # bars. Play till you're out.":"<b>點擊</b>小跳，<b>長按</b>高跳並用光束懸停（落地後 HOVER 條會回滿）。掉進海裡扣一顆愛心 - 你有#顆，有些缺口上方飄著綠色愛心。每#小節回一顆愛心。玩到出局為止。",
"<b>Tap</b> where you want the beam to go - it shoots from the saucer and knocks the first crab it meets back to the sea. Big purple crabs take two hits. The beam <b>overheats</b> if you fire too fast - but a shot <b>on the beat is free</b> and scores double. Every crab that gets through climbs onto the arch: <b>five and it falls</b>. Every # bars the tide takes one crab off the arch. Play till it falls.":"<b>點擊</b>你想讓光束射向的位置 - 光束從飛碟射出，把碰到的第一隻螃蟹打回海裡。紫色大螃蟹要打兩下。射太快光束會<b>過熱</b> - 但<b>踩準節拍的射擊免費</b>，還雙倍得分。每隻漏過去的螃蟹都會爬上石拱：<b>五隻就塌了</b>。每#小節潮水會從石拱上帶走一隻螃蟹。玩到石拱塌掉為止。",
"<b>◀ ▶</b> (or the sides of the screen) to change lane, <b>▲</b> (or the middle) to jump. A big wave across all lanes has to be jumped; rocks have to be dodged. # hearts. A heart back every # bars. Play till you're out.":"<b>◀ ▶</b>（或螢幕兩側）換道，<b>▲</b>（或螢幕中間）跳躍。橫跨所有賽道的大浪必須跳過；岩石必須閃開。#顆愛心。每#小節回一顆愛心。玩到出局為止。",
"<b>The remix:</b> all three games, # bars each - hop the rocks, hold the arch, surf the sea - and round again, faster every lap.":"<b>混音模式：</b>三個遊戲，各#小節 - 跳岩石、守石拱、衝海浪 - 然後再來一圈，每圈更快。",
"One score, <b># hearts</b> for all of it. Island Hopper: tap = hop, hold = fly. Crab Night: tap the crabs - one that gets through costs a heart. Surf: <b>◀ ▶</b> lanes, <b>▲</b> jump. A heart back every # bars, and <b>+#</b> and a heart every lap.":"一個分數，全程<b>#顆愛心</b>。Island Hopper：點擊 = 跳，長按 = 飛。Crab Night：點擊螃蟹 - 漏掉一隻扣一顆愛心。Surf：<b>◀ ▶</b> 換道，<b>▲</b> 跳躍。每#小節回一顆愛心，每圈還有<b>+#</b>和一顆愛心。",
"High up in the sky from the cover - an island of cloud over the cloud sea, the car made of cloud, the birds - and Jo's saucer. <b>Part # · Untangle:</b> birds tied together with strings of light, all in a knot. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面裡的高空 - 雲海上的雲島、雲做的車、鳥群 - 還有 Jo 的飛碟。<b>第#部分 · Untangle：</b>鳥兒被光線連在一起，纏成一團。<b>無盡模式：</b>永不停止 - 每#小節變難一次，每#小節回一顆愛心。",
"High up in the sky from the cover - an island of cloud over the cloud sea, the car made of cloud, the birds - and Jo's saucer. <b>Part # · Bird Code:</b> birds hiding in the cloud, in an order you have to crack. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面裡的高空 - 雲海上的雲島、雲做的車、鳥群 - 還有 Jo 的飛碟。<b>第#部分 · Bird Code：</b>鳥兒躲在雲裡，你得破解牠們的順序。<b>無盡模式：</b>永不停止 - 每#小節變難一次，每#小節回一顆愛心。",
"<b>Drag a bird</b> - move them until no strings cross · every string <span class=\"bl\">blue</span> wins":"<b>拖曳小鳥</b> - 移動牠們直到沒有線交叉 · 所有線變<span class=\"bl\">藍</span>就贏了",
"Move the birds on <span class=\"r\">red</span> strings · every string <span class=\"bl\">blue</span> wins":"移動<span class=\"r\">紅</span>線上的小鳥 · 所有線變<span class=\"bl\">藍</span>就贏了",
"UNTANGLED<small>+#</small>":"解開了！<small>+#</small>",
"<b>Untangled!</b> Here comes a bigger flock":"<b>解開了！</b>更大的鳥群來了",
