"Last try: <span class=\"gd\"></span><b>#</b> right spot · <span class=\"bd\"></span><b>#</b> wrong spot <span class=\"s\">- tap birds for the next try</span><br><span class=\"s\"><span class=\"gd\"></span>right bird, right spot &nbsp;<span class=\"bd\"></span>right bird, wrong spot &nbsp;no bead: not hiding · a bird can hide twice</span>":"上一次：<span class=\"gd\"></span><b>#</b> 個位置對 · <span class=\"bd\"></span><b>#</b> 個位置錯 <span class=\"s\">- 點擊小鳥進行下一次嘗試</span><br><span class=\"s\"><span class=\"gd\"></span>鳥對，位置對 &nbsp;<span class=\"bd\"></span>鳥對，位置錯 &nbsp;沒珠子：沒躲 · 一隻鳥可以躲兩次</span>",
