"The two rooms from the cover, split on the diagonal - hers pink, his purple; her reading with the long red hair, him on his phone in the headphones - and Jo's saucer. <b>Part # · Love Cards:</b> the cards face down on her bed. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的兩個房間，沿對角線分開 - 她的粉紅色，他的紫色；一頭紅色長髮的她在看書，戴著耳機的他在滑手機 - 還有 Jo 的飛碟。<b>第#部分 · Love Cards：</b>她床上背面朝上的卡牌。<b>無盡模式：</b>永不停止 - 每#小節變難一次，每#小節回一顆愛心。",
"The two rooms from the cover, split on the diagonal - hers pink, his purple; her reading with the long red hair, him on his phone in the headphones - and Jo's saucer. <b>Part # · Snap:</b> her pile and his on the floor between them. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的兩個房間，沿對角線分開 - 她的粉紅色，他的紫色；一頭紅色長髮的她在看書，戴著耳機的他在滑手機 - 還有 Jo 的飛碟。<b>第#部分 · Snap：</b>兩人之間地板上她的牌堆和他的牌堆。<b>無盡模式：</b>永不停止 - 每#小節變難一次，每#小節回一顆愛心。",
