"Turn two cards: the same picture is a pair. Remember where the others were - and clear the bed before the time's up. <b>Go again.</b>":"翻兩張牌：圖案相同就是一對。記住其他牌的位置 - 在時間到之前清空床面。<b>再來一次。</b>",
"When both piles show the same picture, tap - SNAP. A heart and a broken heart aren't the same. <b>Go again.</b>":"兩堆出現相同圖案時點擊 - SNAP。愛心和破碎的心可不一樣。<b>再來一次。</b>",
