"Jo's studio at night from the cover - the big speakers, the screen with the crowd, the skull on the desk. On the desk the drum machine: # pads lit from under, each its own note, and Jo's saucer hovering over them. <b>Endless:</b> the patterns never stop - less time every # bars, a heart back every #.":"封面裡夜晚的 Jo 的錄音室 - 大喇叭、顯示著人群的螢幕、桌上的骷髏頭。桌上是鼓機：#個從底下亮起的鼓墊，每個一個音，Jo 的飛碟懸在上面。<b>無盡模式：</b>序列永不停止 - 每#小節時間變短，每#小節回一顆愛心。",
"Up all night and it's all still there.<br>Level # cleared: <b>Pad Memory ∞</b> is open in the gold Endless list.":"熬了一整夜，一切都還在。<br>第#關已過關：<b>Pad Memory ∞</b> 已在金色無盡模式列表中開放。",
"Play the pattern back before the time runs out - one pad a beat is plenty. <b>Go again.</b>":"在時間用完前把序列敲回來 - 一拍一個鼓墊就夠了。<b>再來一次。</b>",
"Watch the order the pads light up in, then play it back the same way - say the colours to yourself. <b>Go again.</b>":"看清鼓墊亮起的順序，再照同樣順序敲回來 - 在心裡默念顏色。<b>再來一次。</b>",
