"All the way down through the city.<br>Level # cleared: <b>Freefall ∞</b> is open in the gold Endless list.":"一路穿過城市落到底。<br>第#關已過關：<b>Freefall ∞</b> 已在金色無盡模式列表中開放。",
"Crane arms swing round. Watch where the arm will be when it reaches you, and slide clear. <b>Go again.</b>":"吊車臂會轉過來。看準它到你這裡時的位置，滑開閃過。<b>再來一次。</b>",
"Each skybridge has one hole - get over it before you drop. Watch the blue ring. <b>Go again.</b>":"每座空橋只有一個洞 - 落下前移到它上方。注意藍色的環。<b>再來一次。</b>",
"Helicopters cross the shaft. See which way they fly and get out of their line. <b>Go again.</b>":"直升機會橫越通道。看清它們飛的方向，閃開航線。<b>再來一次。</b>",
"The window-washers' cradles slide from wall to wall. Time it - or go round the end. <b>Go again.</b>":"擦窗工的吊籃會在兩牆之間滑動。抓準時機 - 或者從尾端繞過去。<b>再來一次。</b>",
