"Deep space from the cover - the rainbow across it, the big gold moon, the two kids in the red flying car - and Jo's saucer. <b>Part # · Planet Match:</b> little planets in the rainbow's colours. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面裡的深空 - 橫跨其中的彩虹、巨大的金色月亮、紅色飛車裡的兩個孩子 - 還有Jo的飛碟。<b>第#部分 · Planet Match：</b>彩虹顏色的小行星。<b>無盡模式：</b>永不停止 - 每#小節更難，每#小節回復一顆愛心。",
"Deep space from the cover - the rainbow across it, the big gold moon, the two kids in the red flying car - and Jo's saucer. <b>Part # · Rainbow Sort:</b> glass tubes, the planets mixed up in them. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面裡的深空 - 橫跨其中的彩虹、巨大的金色月亮、紅色飛車裡的兩個孩子 - 還有Jo的飛碟。<b>第#部分 · Rainbow Sort：</b>玻璃管裡混著各色行星。<b>無盡模式：</b>永不停止 - 每#小節更難，每#小節回復一顆愛心。",
"Deep space from the cover - the rainbow across it, the big gold moon, the two kids in the red flying car - and Jo's saucer. <b>Part # · Star Peaks:</b> three peaks of cards in front of the rainbow. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面裡的深空 - 橫跨其中的彩虹、巨大的金色月亮、紅色飛車裡的兩個孩子 - 還有Jo的飛碟。<b>第#部分 · Star Peaks：</b>彩虹前的三座卡牌山峰。<b>無盡模式：</b>永不停止 - 每#小節更難，每#小節回復一顆愛心。",
