"Planets everywhere.<br>Part #, <b>Rainbow Sort</b>, is open.":"滿天行星。<br>第#部分<b>Rainbow Sort</b>已開放。",
"Every colour in its place.<br>Part #, <b>Star Peaks</b>, is open.":"每種顏色各歸其位。<br>第#部分<b>Star Peaks</b>已開放。",
"Out of this world.<br>Level # cleared: <b>Planet Match ∞</b>, <b>Rainbow Sort ∞</b>, <b>Star Peaks ∞</b> and the <b>Remix ∞</b> are open in the gold Endless list.":"宇宙級精彩。<br>第#關過關：<b>Planet Match ∞</b>、<b>Rainbow Sort ∞</b>、<b>Star Peaks ∞</b>和<b>混音模式 ∞</b>已在金色無盡模式列表中開放。",
"Swap two planets side by side so three or more of a colour line up - and reach the stage's score before the time's up. <b>Go again.</b>":"交換相鄰的兩顆行星，讓三顆或更多同色連成一線 - 在時間結束前達到本階段的分數。<b>再來一次。</b>",
"Lift the top planet of a tube and drop it on the same colour or into an empty tube - one colour to a tube. <b>Go again.</b>":"拿起管子最上面的行星，放到同色行星上或空管裡 - 一管一種顏色。<b>再來一次。</b>",
"Tap a free card one higher or one lower than the pile's top card. Stuck? Tap the deck. <b>Go again.</b>":"點擊一張比牌堆頂牌大一或小一的可用卡牌。卡住了？點牌庫。<b>再來一次。</b>",
