"The houses are quiet again.<br>Level # cleared: <b>Haunted Windows ∞</b> is open in the gold Endless list.":"房子們又安靜下來了。<br>第#關過關：<b>Haunted Windows ∞</b>已在金色無盡模式列表中開放。",
"Eight got away. Tap each ghost while it's up in the window - ten in a row calm the houses down. <b>Go again.</b>":"跑掉了八隻。趁鬼出現在窗戶時點擊它 - 連續十隻能讓房子平靜下來。<b>再來一次。</b>",
"Only the ghosts - the people at the lit windows live there. <b>Go again.</b>":"只抓鬼 - 亮燈窗戶裡的人是住戶。<b>再來一次。</b>",
"The old houses on the street from the cover, at dusk, in the fog. Ghosts come up in the windows on the beat - catch them with the saucer's beam before they duck away. <b>Endless:</b> the ghosts never stop - quicker every # bars, a heart back every #.":"封面上那條街的老房子，黃昏，霧中。鬼魂踩準節拍出現在窗戶 - 在它們躲回去之前用飛碟的光束抓住它們。<b>無盡模式：</b>鬼魂永不停歇 - 每#小節更快，每#小節回復一顆愛心。",
"RUN OVER<small>HAUNTED</small>":"遊戲結束<small>被纏上了</small>",
"High up in the sky from the cover - an island of cloud over the cloud sea, the car made of cloud, the birds - and Jo's saucer. <b>The remix:</b> Untangle and Bird Code, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"封面裡的高空 - 雲海上的雲島、雲朵做的車、飛鳥 - 還有Jo的飛碟。<b>混音模式：</b>Untangle和Bird Code各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Untangle:</b> drag the birds until no two strings cross. <b>Bird Code:</b> tap birds at the front to guess the order they're hiding in - a <b>gold</b> bead is the right bird in the right spot, a <b>blue</b> bead the right bird in the wrong spot. When a game's turn is up you finish what you're on, then the other one comes in.":"<b>Untangle：</b>拖曳小鳥，直到沒有任何兩條線交叉。<b>Bird Code：</b>點擊前排的小鳥，猜出牠們藏著的順序 - <b>金色</b>珠子表示鳥對位置也對，<b>藍色</b>珠子表示鳥對但位置不對。輪到的遊戲時間一到，先完成手上這一局，再換另一個。",
"REMIX<small>both games, till the hearts run out</small>":"混音模式<small>兩個遊戲，玩到愛心耗盡</small>",
