"REMIX OVER<small>THE BIRDS FLEW OFF</small>":"混音結束<small>鳥飛走了</small>",
"<b>#</b> up in the sky · lap <b>#</b> · flocks <b>#</b> · codes <b>#</b>":"高空中<b>#</b> · 第<b>#</b>圈 · 鳥群<b>#</b> · 密碼<b>#</b>",
"The two rooms from the cover, split on the diagonal - hers pink, his purple; her reading with the long red hair, him on his phone in the headphones - and Jo's saucer. <b>The remix:</b> Love Cards and Snap, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"封面裡沿對角線分開的兩個房間 - 她的是粉紅色，他的是紫色；紅色長髮的她在看書，戴著耳機的他在滑手機 - 還有Jo的飛碟。<b>混音模式：</b>Love Cards和Snap各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Love Cards:</b> tap two cards to turn them - the same picture is a pair and the saucer beams them up; clear the bed before the time's up. <b>Snap:</b> on every beat both piles turn a card - the same picture on both: <b>tap anywhere</b> (or Space). A heart and a broken heart aren't the same. A snap on no pair, a pair let by, or running out of time costs a heart (#). When a game's turn is up you finish what you're on, then the other one comes in.":"<b>Love Cards：</b>點擊兩張卡牌翻開 - 圖案相同就是一對，飛碟會把它們吸走；在時間結束前清空床面。<b>Snap：</b>每個節拍兩疊牌各翻一張 - 兩邊圖案相同時：<b>點擊任意位置</b>（或按Space）。愛心和破碎的愛心不一樣。沒有對子時拍下、放過一對、或時間用完，都會扣一顆愛心（#）。輪到的遊戲時間一到，先完成手上這一局，再換另一個。",
"LAP #<small>LOVE CARDS · +#</small>":"第#圈<small>LOVE CARDS · +#</small>",
"LAP #<small>LOVE CARDS · +# · a heart back</small>":"第#圈<small>LOVE CARDS · +# · 回復一顆愛心</small>",
