"REMIX OVER<small>OUT OF TIME</small>":"混音結束<small>時間到</small>",
"REMIX OVER<small>MISSED A PAIR</small>":"混音結束<small>漏了一對</small>",
"REMIX OVER<small>NOT A PAIR</small>":"混音結束<small>不是一對</small>",
"<b>#</b> in their rooms · lap <b>#</b> · pairs <b>#</b> · snaps <b>#</b>":"房間裡<b>#</b> · 第<b>#</b>圈 · 對子<b>#</b> · 拍中<b>#</b>",
"The sky from the cover - pink and white clouds, the open book floating on them with the lavender smoke heart - and Jo's saucer. <b>The remix:</b> Heart Pop, Love Words and Heart Merge, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"封面裡的天空 - 粉白相間的雲，雲上漂浮著一本打開的書和薰衣草色的煙霧愛心 - 還有Jo的飛碟。<b>混音模式：</b>Heart Pop、Love Words和Heart Merge各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Heart Pop:</b> drag to aim, let go to shoot - three or more of a colour touching burst. <b>Love Words:</b> drag from a word's first letter to its last. <b>Heart Merge:</b> swipe - two the same become one. When a game's turn is up you finish what you're on, then the next one comes in.":"<b>Heart Pop：</b>拖曳瞄準，放開發射 - 三個以上同色相連就會爆開。<b>Love Words：</b>從單字的首字母拖到末字母。<b>Heart Merge：</b>滑動 - 兩個相同的合成一個。輪到的遊戲時間一到，先完成手上這一局，再換下一個。",
"LAP #<small>HEART POP · +#</small>":"第#圈<small>HEART POP · +#</small>",
"LAP #<small>HEART POP · +# · a heart back</small>":"第#圈<small>HEART POP · +# · 回復一顆愛心</small>",
