"<b>#</b> in the clouds · lap <b>#</b> · popped <b>#</b> · words <b>#</b> · merges <b>#</b>":"雲端<b>#</b> · 第<b>#</b>圈 · 爆破<b>#</b> · 單字<b>#</b> · 合成<b>#</b>",
"The city at sunset from the cover, high over the towers - the sky going from purple to fire, the towers lit. <b>The remix:</b> Rooftop Golf and Sky Hockey, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"封面裡日落時分的城市，高懸在摩天大樓之上 - 天空由紫轉為火紅，大樓燈火通明。<b>混音模式：</b>Rooftop Golf和Sky Hockey各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Rooftop Golf:</b> put a finger down anywhere, pull back and let go to putt - fewer strokes, more points; out of time on a hole, or # strokes, costs a heart. <b>Sky Hockey:</b> move your golden striker and hit the puck into the far goal - first to # takes a round; losing a round costs a heart. When a game's turn is up you finish the hole or round you're on, then the other one comes in.":"<b>Rooftop Golf：</b>手指隨便按住一處，往後拉再放開推桿 - 桿數越少積分越多；一洞超時或打到#桿，扣一顆愛心。<b>Sky Hockey：</b>移動你的金色擊球器，把冰球打進對面球門 - 先得#分贏一局；輸一局扣一顆愛心。輪到的遊戲時間一到，先打完手上這一洞或這一局，再換另一個。",
"LAP #<small>ROOFTOP GOLF · +#</small>":"第#圈<small>ROOFTOP GOLF · +#</small>",
"LAP #<small>ROOFTOP GOLF · +# · a heart back</small>":"第#圈<small>ROOFTOP GOLF · +# · 回復一顆愛心</small>",
"REMIX OVER<small>PICKED UP</small>":"混音結束<small>撿球放棄</small>",
"REMIX OVER<small>THE SHADOW TAKES ROUND #</small>":"混音結束<small>影子贏下第#局</small>",
"<b>#</b> on the roofs · lap <b>#</b> · holes <b>#</b> · rounds <b>#</b>":"屋頂上<b>#</b> · 第<b>#</b>圈 · 球洞<b>#</b> · 局數<b>#</b>",
"The wet street from the cover at night, in the rain. <b>The remix:</b> Unblock and Light Link, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"封面裡夜晚濕漉漉的街道，雨中。<b>混音模式：</b>Unblock和Light Link各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Unblock:</b> drag the cars along their lines until the blue one can drive out on the right. <b>Light Link:</b> tap the mirrors to turn them and bend the beam to the car - umbrellas block the light. When a game's turn is up you finish what you're on, then the other one comes in.":"<b>Unblock：</b>沿著軌道拖曳車輛，直到藍色的車能從右邊開出去。<b>Light Link：</b>點擊鏡子旋轉，把光束折射到車上 - 雨傘會擋住光線。輪到的遊戲時間一到，先完成手上這一局，再換另一個。",
"LAP #<small>UNBLOCK · +#</small>":"第#圈<small>UNBLOCK · +#</small>",
