"<b>#</b> in the rain · lap <b>#</b> · car parks <b>#</b> · streets <b>#</b>":"雨中<b>#</b> · 第<b>#</b>圈 · 停車場<b>#</b> · 街道<b>#</b>",
"The night from the cover - the stars, the lasers crossing over the black car with the glowing pink hood and the rider on its roof - and Jo's saucer. <b>The remix:</b> Neon Pinball and Speaker Push, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"封面裡的夜晚 - 星星、在黑色汽車上方交錯的雷射，車子有發光的粉紅色引擎蓋，車頂上還有個人 - 還有Jo的飛碟。<b>混音模式：</b>Neon Pinball和Speaker Push各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Neon Pinball:</b> tap to launch, then hold the left or the right of the screen for each flipper (or the arrows). <b>Speaker Push:</b> push every speaker onto a glowing pad with the arrows, a swipe or a tap - the saucer can push but never pull. When a game's turn is up you finish the floor or the ball you're on - losing that ball costs nothing - then the other one comes in.":"<b>Neon Pinball：</b>點擊發射，然後長按螢幕左側或右側控制對應的擋板（或用方向鍵）。<b>Speaker Push：</b>用方向鍵、滑動或點擊，把每個喇叭推到發光的踏板上 - 飛碟只能推不能拉。輪到的遊戲時間一到，先完成手上這一層或這一球 - 這一球掉了也不扣 - 再換另一個。",
"LAP #<small>NEON PINBALL · +#</small>":"第#圈<small>NEON PINBALL · +#</small>",
"LAP #<small>NEON PINBALL · +# · a heart back</small>":"第#圈<small>NEON PINBALL · +# · 回復一顆愛心</small>",
"REMIX OVER<small>DRAINED</small>":"混音結束<small>球掉了</small>",
"<b>#</b> under the lasers · lap <b>#</b> · hits <b>#</b> · floors <b>#</b>":"雷射下<b>#</b> · 第<b>#</b>圈 · 擊中<b>#</b> · 層數<b>#</b>",
"The beach from the cover at night - the glowing heart over the sea, the crescent moon, the waves, the red pickup with its headlights on - and Jo's saucer. <b>The remix:</b> Heart Flow, Crab Sweeper, Starlight and Shell Sudoku, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"封面裡夜晚的海灘 - 海面上發光的愛心、彎彎的月牙、海浪、亮著車燈的紅色皮卡 - 還有Jo的飛碟。<b>混音模式：</b>Heart Flow、Crab Sweeper、Starlight和Shell Sudoku各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Heart Flow:</b> drag from a heart to the heart of the same colour; lines can't cross. <b>Crab Sweeper:</b> tap a mound to dig it, the number counts the crabs around; hold it, or turn on <b>FLAG</b>, to mark a crab - and keep digging, or the tide takes a heart. <b>Starlight:</b> tap a star and it changes, with the four next to it; light them all. <b>Shell Sudoku:</b> tap a picture on the tray, then a stone; each one once in every row, column and box. When a game's turn is up you finish what you're on, then the next one comes in.":"<b>Heart Flow：</b>從一顆愛心拖到同色的愛心；線不能交叉。<b>Crab Sweeper：</b>點擊沙堆挖開，數字表示周圍的螃蟹數；長按或打開<b>插旗</b>來標記螃蟹 - 要一直挖，不然潮水會捲走一顆愛心。<b>Starlight：</b>點擊一顆星星，它和相鄰的四顆都會切換；把它們全部點亮。<b>Shell Sudoku：</b>先點托盤上的圖案，再點一塊石頭；每列、每行、每宮中每個圖案各出現一次。輪到的遊戲時間一到，先完成手上這一局，再換下一個。",
"REMIX<small>all four games, till the hearts run out</small>":"混音模式<small>四個遊戲，玩到愛心耗盡</small>",
"LAP #<small>HEART FLOW · +#</small>":"第#圈<small>HEART FLOW · +#</small>",
"LAP #<small>HEART FLOW · +# · a heart back</small>":"第#圈<small>HEART FLOW · +# · 回復一顆愛心</small>",
