"REMIX OVER<small>THE TIDE</small>":"混音結束<small>潮水來了</small>",
"<b>#</b> on the beach · lap <b>#</b> · pairs <b>#</b> · mounds <b>#</b> · taps <b>#</b> · pictures <b>#</b>":"海灘上<b>#</b> · 第<b>#</b>圈 · 配對<b>#</b> · 沙堆<b>#</b> · 點擊<b>#</b> · 圖案<b>#</b>",
"The Dust Sea. <b>The remix:</b> Somebody and Zirka's Ride, # bars each, and round again, harder every lap. A finished lap gives a heart back.":"Dust Sea。<b>混音模式：</b>Somebody和Zirka's Ride各#小節，循環往復，每圈更難。跑完一圈回復一顆愛心。",
"<b>Somebody:</b> drag to fly, the beam fires on its own. <b>Zirka's Ride:</b> tap a side to swerve, tap the middle to jump. <b># hearts</b> and one score for both. When a game's turn is up you finish what you're on, then the other one comes in.":"<b>Somebody：</b>拖曳飛行，光束自動發射。<b>Zirka's Ride：</b>點擊兩側閃避，點擊中間跳躍。<b>#顆愛心</b>，兩個遊戲共用一個分數。輪到的遊戲時間一到，先完成手上這一局，再換另一個。",
"ZIRKA'S RIDE<small>tap a side to swerve - tap the middle to jump</small>":"ZIRKA'S RIDE<small>點兩側閃避 - 點中間跳躍</small>",
